if(!EditorApplication.isPlaying || UnityEngine.SceneManagement.SceneManager.GetActiveScene().path!="Assets/Scenes/CM_CrookedMortar_UsabilityBlockout01.unity")throw new System.Exception("Usability blockout Play mode required");
var door=UnityEngine.Object.FindFirstObjectByType<BlightBloom.Prototypes.BlockoutDoor>();var player=door.player;var cc=player.GetComponent<CharacterController>();var previousKeyboard=UnityEngine.InputSystem.Keyboard.current;var keyboard=UnityEngine.InputSystem.InputSystem.AddDevice<UnityEngine.InputSystem.Keyboard>("CM_DoorInputRegression");var previousBackground=Application.runInBackground;Application.runInBackground=true;
var action=(UnityEngine.InputSystem.InputAction)typeof(BlightBloom.Prototypes.BlockoutDoor).GetField("interact",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(door);
var events=new System.Collections.Generic.List<string>();System.Action<UnityEngine.InputSystem.InputAction.CallbackContext> observe=c=>events.Add(c.control.path);action.performed+=observe;
var checks=new System.Collections.Generic.List<object>();var routes=new System.Collections.Generic.List<object>();bool allPassed=true;int stage=0;double until=0;EditorApplication.CallbackFunction callback=null;
void Check(string name,bool result,object detail=null){checks.Add(new{name,passed=result,detail});allPassed&=result;}
void Position(float x,float y,float z){cc.enabled=false;player.position=new Vector3(x,y,z);cc.enabled=true;Physics.SyncTransforms();}
void E(){UnityEngine.InputSystem.InputSystem.QueueStateEvent(keyboard,new UnityEngine.InputSystem.LowLevel.KeyboardState(UnityEngine.InputSystem.Key.E));UnityEngine.InputSystem.InputSystem.Update();UnityEngine.InputSystem.InputSystem.QueueStateEvent(keyboard,new UnityEngine.InputSystem.LowLevel.KeyboardState());UnityEngine.InputSystem.InputSystem.Update();}
bool Go(string name,float x,float z){for(int i=0;i<600;i++){var before=player.position;var delta=new Vector3(x-before.x,0,z-before.z);if(delta.magnitude<.06f)break;cc.Move(Vector3.ClampMagnitude(delta,.04f)+Vector3.down*.045f);Physics.SyncTransforms();if(i>30&&(player.position-before).sqrMagnitude<.00000001f)break;}bool ok=Vector2.Distance(new Vector2(player.position.x,player.position.z),new Vector2(x,z))<.16f&&Mathf.Abs(player.position.y-.24f)<.17f;routes.Add(new{name,passed=ok,actual=player.position.ToString("F3")});allPassed&=ok;return ok;}
void Finish(string error=null){EditorApplication.update-=callback;action.performed-=observe;UnityEngine.InputSystem.InputSystem.RemoveDevice(keyboard);if(previousKeyboard!=null)previousKeyboard.MakeCurrent();Application.runInBackground=previousBackground;System.IO.File.WriteAllText("ArtSource/Blender/Architecture/CrookedMortar/UsabilityBlockout01/DoorInteractionValidation.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{passed=allPassed&&error==null,error,method="Queued E press/release through a temporary Input System keyboard, existing Player/Interact bindings with a scene-local Press interaction and normal live MonoBehaviour updates. No SetOpen/OnInteract/Update invocation. CharacterController.Move used only for passage checks.",checks,routes,inputEvents=events,actionEnabled=action.enabled,systemsEnabled=cc.enabled&&player.GetComponent<BlightBloom.Traversal.ThirdPersonMotor>().enabled&&player.GetComponent<BlightBloom.Traversal.TraversalInput>().enabled&&UnityEngine.Object.FindFirstObjectByType<BlightBloom.Traversal.ThirdPersonOrbitCamera>().enabled},Newtonsoft.Json.Formatting.Indented));}
callback=()=>{try{if(EditorApplication.timeSinceStartup<until)return;switch(stage++){
case 0:var doorLeaf=door.GetComponentInChildren<BoxCollider>();var walls=GameObject.Find("01 Wall shell - clear dimensions in metres").GetComponentsInChildren<Collider>();var clashes=new System.Collections.Generic.List<string>();for(float a=0;a<=105;a+=2.5f){var rotation=Quaternion.Euler(0,a,0);var position=door.transform.position+rotation*doorLeaf.transform.localPosition;foreach(var wall in walls)if(Physics.ComputePenetration(doorLeaf,position,rotation,wall,wall.transform.position,wall.transform.rotation,out _,out float depth)&&depth>.001f)clashes.Add(wall.name+" @ "+a+" deg, "+depth+"m");}Check("Outward leaf clears frame throughout 105-degree sweep",clashes.Count==0,clashes);Check("Existing E binding enabled",action.enabled&&action.bindings.Any(b=>b.path=="<Keyboard>/e"));Position(4,.04f,-4.5f);E();Check("Out of range E ignored",!door.IsOpen);Position(3.7f,.24f,-1.2f);E();Check("Normal front approach E requests opening",door.IsOpen);until=EditorApplication.timeSinceStartup+2.0;break;
case 1:Check("Actual sweep pauses with player in the way",door.IsBlocked&&door.transform.localEulerAngles.y<104,door.transform.localEulerAngles.y);var leaf=door.GetComponentInChildren<BoxCollider>();Check("Paused leaf does not penetrate player",!Physics.ComputePenetration(leaf,leaf.transform.position,leaf.transform.rotation,cc,cc.transform.position,cc.transform.rotation,out _,out _));Position(4,.24f,-2.7f);until=EditorApplication.timeSinceStartup+2.0;break;
case 2:Check("Opening resumes to 105 degrees after stepping clear",!door.IsBlocked&&Mathf.Abs(Mathf.DeltaAngle(door.transform.localEulerAngles.y,105))<.1f,door.transform.localEulerAngles.y);Go("Open front entrance",3.8f,.6f);Go("Shop circulation",3.6f,3.3f);Go("Kitchen access door open",6.2f,3.3f);Go("Return shop",3.6f,3.3f);Go("Inside interaction point",3.7f,1);E();Check("Inside E requests closing",!door.IsOpen);until=EditorApplication.timeSinceStartup+2.0;break;
case 3:Check("Door fully closes from E",Mathf.Abs(Mathf.DeltaAngle(door.transform.localEulerAngles.y,0))<.1f&&!door.IsBlocked);Go("Shop route door closed",3.6f,3.3f);Go("Kitchen access door closed",6.2f,3.3f);Go("Return shop closed",3.6f,3.3f);Go("Inside E point",3.7f,1);E();until=EditorApplication.timeSinceStartup+2.0;break;
case 4:Check("Repeated E opens normally",door.IsOpen&&Mathf.Abs(Mathf.DeltaAngle(door.transform.localEulerAngles.y,105))<.1f);Position(3.7f,.24f,-1.2f);E();until=EditorApplication.timeSinceStartup+2.0;break;
case 5:Check("Closing also pauses for player",!door.IsOpen&&door.IsBlocked&&Mathf.Abs(Mathf.DeltaAngle(door.transform.localEulerAngles.y,0))>.1f,door.transform.localEulerAngles.y);Position(3.7f,.24f,1);until=EditorApplication.timeSinceStartup+2.0;break;
case 6:Check("Closing resumes after player clears",!door.IsBlocked&&Mathf.Abs(Mathf.DeltaAngle(door.transform.localEulerAngles.y,0))<.1f);Position(3.7f,3.64f,1);E();Check("Upper floor cannot trigger downstairs door",!door.IsOpen);Position(4,.04f,-3.8f);Check("Received bound keyboard events",events.Count>=6,new{count=events.Count});Finish();break;
}}catch(System.Exception ex){allPassed=false;Finish(ex.ToString());}};
EditorApplication.update+=callback;return "Live E-key regression scheduled (about 15 seconds); results in DoorInteractionValidation.json";
